@startuml

class City {
  + name : string
  + inhabitants : int
}

class Attraction {
  + name : string
  + address : string
}

class GuidedTour {
  + duration : int
}

class Discount {
  + amount : int
}

class Person {
  + name : string
}

class Visitor extends Person {}

class Guide extends Person {}

City "1" -- "*" Attraction : has
Attraction "1" -- "*" GuidedTour : offers
GuidedTour "1" -- "1" Guide : requires
GuidedTour "0..1" -- "0..1" Visitor : participates
GuidedTour "0..*" -- "0..1" Discount : granted to

@enduml

